-- 02_seed.sql : 분야 7개 + 오프닝 128개 (자동 생성, 수순은 python-chess로 합법성 검증됨)
-- 새로 설치할 때 한 번 실행하세요. 다시 실행하면 사이트에서 고친 수순이 이 파일 내용으로 되돌아갑니다.
begin;

on conflict (id) do update set name = excluded.name, description = excluded.description, weight = excluded.weight, ai = excluded.ai, sort = excluded.sort;

on conflict (id) do update set slug = excluded.slug, name = excluded.name, grp = excluded.grp, side = excluded.side, san = excluded.san, uci = excluded.uci, fens = excluded.fens, sort = excluded.sort;

select setval(pg_get_serial_sequence('public.openings', 'id'), (select max(id) from public.openings));
commit;
